functions {
  vector adstock(vector x, real r) {
    int n = rows(x);
    vector[n] w;
    w[1] = 1;
    for (l in 2:n) {
      w[l] = w[l - 1] * r;
    }
    w /= sum(w);
    vector[n] a;
    for (t in 1:n) {
      a[t] = dot_product(w[1:t], reverse(x[1:t]));
    }
    return a;
  }
  vector hill(vector a, real k, real n) {
    vector[rows(a)] h;
    for (t in 1:rows(a)) {
      h[t] = a[t] > 0 ? inv_logit(n * (log(a[t]) - log(k))) : 0;
    }
    return h;
  }
  vector saturate(vector a, real k, vector slope, int m) {
    if (rows(slope) == 0) {
      return tanh(atanh(0.5) * a / k);
    }
    return hill(a, k, slope[m]);
  }
  matrix saturated(matrix spend, array[] int window, vector retention, vector half,
                   vector slope) {
    matrix[size(window), cols(spend)] h;
    for (m in 1:cols(spend)) {
      vector[rows(spend)] a = adstock(spend[:, m], retention[m]);
      h[:, m] = saturate(a[window], half[m], slope, m);
    }
    return h;
  }
  vector tested(matrix treated, matrix untreated, array[] int test_channel, array[] int readout,
                vector beta, vector retention, vector half, vector slope, int R) {
    vector[R] mean;
    int r = 1;
    for (k in 1:size(readout)) {
      int m = test_channel[k];
      int L = cols(treated);
      vector[L] ht = saturate(adstock(treated[k]', retention[m]), half[m], slope, m);
      vector[L] hc = saturate(adstock(untreated[k]', retention[m]), half[m], slope, m);
      int n = L - readout[k] + 1;
      mean[r:(r + n - 1)] = beta[m] * (ht[readout[k]:L] - hc[readout[k]:L]);
      r += n;
    }
    return mean;
  }
  vector estimated(matrix as_run, matrix as_planned, array[] int estimate_channel,
                   array[] int estimate_readout, vector beta, vector retention, vector half,
                   vector slope) {
    int L = cols(as_run);
    vector[size(estimate_readout)] mean;
    for (e in 1:size(estimate_readout)) {
      int m = estimate_channel[e];
      vector[L] hr = saturate(adstock(as_run[e]', retention[m]), half[m], slope, m);
      vector[L] hp = saturate(adstock(as_planned[e]', retention[m]), half[m], slope, m);
      mean[e] = beta[m] * sum(hr[estimate_readout[e]:L] - hp[estimate_readout[e]:L]);
    }
    return mean;
  }
  vector mediated(matrix run1, matrix planned1, array[] int channel1, array[] int from1,
                  vector beta1, vector retention1, vector half1, vector slope1, matrix run2,
                  matrix planned2, array[] int channel2, array[] int from2, vector beta2,
                  vector retention2, vector half2, vector slope2, real gamma) {
    int D = size(channel1);
    int L1 = cols(run1);
    int L2 = cols(run2);
    vector[D] mean;
    for (d in 1:D) {
      int m = channel1[d];
      vector[L1] hr = saturate(adstock(run1[d]', retention1[m]), half1[m], slope1, m);
      vector[L1] hp = saturate(adstock(planned1[d]', retention1[m]), half1[m], slope1, m);
      mean[d] = gamma * beta1[m] * sum(hr[from1[d]:L1] - hp[from1[d]:L1]);
      if (channel2[d] > 0) {
        int k = channel2[d];
        vector[L2] gr = saturate(adstock(run2[d]', retention2[k]), half2[k], slope2, k);
        vector[L2] gp = saturate(adstock(planned2[d]', retention2[k]), half2[k], slope2, k);
        mean[d] += beta2[k] * sum(gr[from2[d]:L2] - gp[from2[d]:L2]);
      }
    }
    return mean;
  }
}
data {
  int<lower=1> N;
  int<lower=1> L1;
  array[N] int<lower=1, upper=L1> window1;
  int<lower=0, upper=N> O1;
  array[O1] int<lower=1, upper=N> observed1;
  vector[O1] y1;
  int<lower=1> M1;
  matrix[L1, M1] spend1;
  vector<lower=0>[M1] window_spend1;
  vector[M1] roi_mu1;
  vector<lower=0>[M1] roi_sigma1;
  int<lower=0> P1;
  matrix[N, P1] calendar1;
  int<lower=0> C1;
  matrix[N, C1] controls1;
  vector[C1] control_lower1;
  vector[C1] control_upper1;
  int<lower=0, upper=1> tanh_curve1;
  int<lower=0> E1;
  array[E1] int<lower=1, upper=M1> estimate_channel1;
  matrix[E1, L1] as_run1;
  matrix[E1, L1] as_planned1;
  array[E1] int<lower=1, upper=L1> estimate_readout1;
  vector[E1] lift1;
  vector<lower=0>[E1] lift_se1;
  int<lower=1> L2;
  array[N] int<lower=1, upper=L2> window2;
  int<lower=0, upper=N> O2;
  array[O2] int<lower=1, upper=N> observed2;
  vector[O2] y2;
  int<lower=1> M2;
  matrix[L2, M2] spend2;
  vector<lower=0>[M2] window_spend2;
  vector[M2] roi_mu2;
  vector<lower=0>[M2] roi_sigma2;
  int<lower=0> P2;
  matrix[N, P2] calendar2;
  int<lower=0> C2;
  matrix[N, C2] controls2;
  vector[C2] control_lower2;
  vector[C2] control_upper2;
  int<lower=0, upper=1> tanh_curve2;
  int<lower=0> E2;
  array[E2] int<lower=1, upper=M2> estimate_channel2;
  matrix[E2, L2] as_run2;
  matrix[E2, L2] as_planned2;
  array[E2] int<lower=1, upper=L2> estimate_readout2;
  vector[E2] lift2;
  vector<lower=0>[E2] lift_se2;
  int<lower=1, upper=C2> mediator;
  real<lower=0> mediator_sd;
  real<lower=0> mediator_unit;
  int<lower=0> D;
  array[D] int<lower=1, upper=M1> channel1;
  matrix[D, L1] run1;
  matrix[D, L1] planned1;
  array[D] int<lower=1, upper=L1> from1;
  array[D] int<lower=0, upper=M2> channel2;
  matrix[D, L2] run2;
  matrix[D, L2] planned2;
  array[D] int<lower=1, upper=L2> from2;
  vector[D] mediated_lift;
  vector<lower=0>[D] mediated_se;
}
parameters {
  vector[M1] log_roi1;
  vector<lower=0, upper=1>[M1] retention1;
  vector<lower=0>[M1] half1;
  vector<lower=0>[tanh_curve1 ? 0 : M1] slope1;
  real intercept1;
  vector[P1] calendar_coef1;
  vector<lower=control_lower1, upper=control_upper1>[C1] control_coef1;
  real<lower=0> sigma1;
  vector[M2] log_roi2;
  vector<lower=0, upper=1>[M2] retention2;
  vector<lower=0>[M2] half2;
  vector<lower=0>[tanh_curve2 ? 0 : M2] slope2;
  real intercept2;
  vector[P2] calendar_coef2;
  vector<lower=control_lower2, upper=control_upper2>[C2] control_coef2;
  real<lower=0> sigma2;
}
model {
  matrix[N, M1] h1 = saturated(spend1, window1, retention1, half1, slope1);
  vector[M1] beta1 = exp(log_roi1) .* window_spend1 ./ (rep_row_vector(1, N) * h1)';
  vector[N] mu1 = intercept1 + calendar1 * calendar_coef1 + controls1 * control_coef1 + h1 * beta1;
  vector[E1] l1 = estimated(as_run1, as_planned1, estimate_channel1, estimate_readout1, beta1,
                            retention1, half1, slope1);
  matrix[N, M2] h2 = saturated(spend2, window2, retention2, half2, slope2);
  vector[M2] beta2 = exp(log_roi2) .* window_spend2 ./ (rep_row_vector(1, N) * h2)';
  vector[N] mu2 = intercept2 + calendar2 * calendar_coef2 + controls2 * control_coef2 + h2 * beta2;
  vector[E2] l2 = estimated(as_run2, as_planned2, estimate_channel2, estimate_readout2, beta2,
                            retention2, half2, slope2);
  real gamma = control_coef2[mediator] / mediator_sd * mediator_unit;
  vector[D] m = mediated(run1, planned1, channel1, from1, beta1, retention1, half1, slope1, run2,
                         planned2, channel2, from2, beta2, retention2, half2, slope2, gamma);
  log_roi1 ~ normal(roi_mu1, roi_sigma1);
  retention1 ~ beta(1, 3);
  half1 ~ lognormal(0, 1);
  slope1 ~ lognormal(0, 0.5);
  intercept1 ~ normal(1, 1);
  calendar_coef1 ~ std_normal();
  control_coef1 ~ std_normal();
  sigma1 ~ std_normal();
  y1 ~ normal(mu1[observed1], sigma1);
  lift1 ~ normal(l1, lift_se1);
  log_roi2 ~ normal(roi_mu2, roi_sigma2);
  retention2 ~ beta(1, 3);
  half2 ~ lognormal(0, 1);
  slope2 ~ lognormal(0, 0.5);
  intercept2 ~ normal(1, 1);
  calendar_coef2 ~ std_normal();
  control_coef2 ~ std_normal();
  sigma2 ~ std_normal();
  y2 ~ normal(mu2[observed2], sigma2);
  lift2 ~ normal(l2, lift_se2);
  mediated_lift ~ normal(m, mediated_se);
}
generated quantities {
  vector[O1 + E1 + O2 + E2 + D] log_lik;
  {
    matrix[N, M1] h1 = saturated(spend1, window1, retention1, half1, slope1);
    vector[M1] beta1 = exp(log_roi1) .* window_spend1 ./ (rep_row_vector(1, N) * h1)';
    vector[N] mu1 = intercept1 + calendar1 * calendar_coef1 + controls1 * control_coef1 + h1 * beta1;
    vector[E1] l1 = estimated(as_run1, as_planned1, estimate_channel1, estimate_readout1, beta1,
                              retention1, half1, slope1);
    matrix[N, M2] h2 = saturated(spend2, window2, retention2, half2, slope2);
    vector[M2] beta2 = exp(log_roi2) .* window_spend2 ./ (rep_row_vector(1, N) * h2)';
    vector[N] mu2 = intercept2 + calendar2 * calendar_coef2 + controls2 * control_coef2 + h2 * beta2;
    vector[E2] l2 = estimated(as_run2, as_planned2, estimate_channel2, estimate_readout2, beta2,
                              retention2, half2, slope2);
    real gamma = control_coef2[mediator] / mediator_sd * mediator_unit;
    vector[D] m = mediated(run1, planned1, channel1, from1, beta1, retention1, half1, slope1, run2,
                           planned2, channel2, from2, beta2, retention2, half2, slope2, gamma);
    for (o in 1:O1) {
      log_lik[o] = normal_lpdf(y1[o] | mu1[observed1[o]], sigma1);
    }
    for (e in 1:E1) {
      log_lik[O1 + e] = normal_lpdf(lift1[e] | l1[e], lift_se1[e]);
    }
    for (o in 1:O2) {
      log_lik[O1 + E1 + o] = normal_lpdf(y2[o] | mu2[observed2[o]], sigma2);
    }
    for (e in 1:E2) {
      log_lik[O1 + E1 + O2 + e] = normal_lpdf(lift2[e] | l2[e], lift_se2[e]);
    }
    for (d in 1:D) {
      log_lik[O1 + E1 + O2 + E2 + d] = normal_lpdf(mediated_lift[d] | m[d], mediated_se[d]);
    }
  }
}
